import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

bool _registered = false;

/// Dart/plugin notices are generated by Flutter. Include the native BLE runtime
/// dependency too, since its Swift package license is outside Flutter's scan.
void registerNativeLicenses() {
  if (_registered) return;
  _registered = true;
  LicenseRegistry.addLicense(() async* {
    yield LicenseEntryWithLineBreaks(
      ['SwiftProtobuf (iOS BLE dependency)'],
      await rootBundle.loadString('assets/licenses/swift_protobuf_LICENSE.txt'),
    );
  });
}
